def prime_factorization(n):
    factors = {}
    d = 2
    temp = n
    while d * d <= temp:
        while temp % d == 0:
            factors[d] = factors.get(d, 0) + 1
            temp //= d
        d += 1
    if temp > 1:
        factors[temp] = factors.get(temp, 0) + 1
    return factors

def tau(n):
    if n == 1:
        return 1
    factors = prime_factorization(n)
    num_divisors = 1
    for exponent in factors.values():
        num_divisors *= (exponent + 1)
    return num_divisors

results = {}
for k in range(1, 11):
    N = 2 * (k**3)
    tau_N = tau(N)
    target = 2 * k
    is_equal = tau_N == target
    results[k] = {
        "N": N,
        "tau(N)": tau_N,
        "2k": target,
        "Equal": is_equal
    }

print("k | N = 2k^3 | tau(2k^3) | 2k | Equal")
